mapper.select:
SELECT 
FROM portfolio_sections section
WHERE section.portfolio_section_id = #{portfolioSectionId}

mapper.insert:
INSERT INTO portfolio_sections (
    section_type, content_mode, section_title, section_subtitle, start_date, end_date,
    current_yn, external_url, thumbnail_file_id, content_json, content_html, content_text,
    layout_type, sort_order, visibility
) VALUES (
    #{sectionType}, #{contentMode}, #{sectionTitle}, #{sectionSubtitle}, #{startDate}, #{endDate},
    #{currentYn}, #{externalUrl}, #{thumbnailFileId}, CAST(#{contentJson} AS JSON), #{contentHtml}, #{contentText},
    #{layoutType}, #{sortOrder}, #{visibility}
)

mapper.update:
UPDATE portfolio_sections
SET use_yn = 'N', version_number = version_number + 1, updated_at = CURRENT_TIMESTAMP(6)
WHERE portfolio_section_id = #{portfolioSectionId}
  AND version_number = #{versionNumber}
  AND use_yn = 'Y'
